-- Loja inicial: 11 perfumes do Shopping China, preço = custo × 1,45 (consulta de 24/10/2026)
on conflict (id) do update set price=excluded.price, volume=excluded.volume, data=excluded.data, active=true, updated_at=now();

on conflict (product_id) do update set supplier_name=excluded.supplier_name, supplier_url=excluded.supplier_url, cost=excluded.cost, updated_at=now();
